import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { getDocument } from "pdfjs-dist/legacy/build/pdf.mjs";
import { parseWithMapping } from "@kys/statement";
import { pdfToStatementCsv, readPdfStatement, type PdfJsLike, type PdfPage } from "../src/pdf-statement";

// Mock statements with made-up people and numbers, generated by fixtures/make_pdfs.py.
const dir = new URL("./fixtures/", import.meta.url);
const truth = JSON.parse(readFileSync(new URL("truth.json", dir), "utf8")) as Record<string, { rows: number; out: number; in: number; first: string }>;
const pdfjs = { getDocument: (src) => getDocument({ ...src, useSystemFonts: true }) } as PdfJsLike;

describe("PDF statements", () => {
  for (const name of ["revolut", "monzo", "barclays", "revolut-2026"]) {
    it(`reads every row of a ${name}-style statement`, async () => {
      const bytes = readFileSync(new URL(`${name}.pdf`, dir));
      const { result, pdf } = await readPdfStatement(pdfjs, bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength), parseWithMapping);
      const t = truth[name]!;
      expect(pdf.rows).toBe(t.rows);
      expect(result.transactions).toHaveLength(t.rows);
      const out = result.transactions.filter((x) => x.amount < 0).reduce((s, x) => s - x.amount, 0);
      const inn = result.transactions.filter((x) => x.amount > 0).reduce((s, x) => s + x.amount, 0);
      expect(out).toBeCloseTo(t.out, 2);
      expect(inn).toBeCloseTo(t.in, 2);
      expect(result.bank).toMatchObject({ id: name.replace(/-.*/, "") });
      if (name !== "revolut-2026") expect(result.dateRange).toEqual({ from: "2026-07-01", to: "2026-07-30" });
    });
  }

  it("keeps Revolut's 'To:' line as the raw descriptor but drops card numbers and references", async () => {
    const bytes = readFileSync(new URL("revolut.pdf", dir));
    const { result, pdf } = await readPdfStatement(pdfjs, bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength), parseWithMapping);
    expect(pdf.csv).not.toMatch(/Card: |535522|Reference: /);
    const shop = result.transactions.find((x) => x.rawPayee === "Tesco");
    expect(shop?.rawDescription).toMatch(/^TESCO STORES 3456/);
    // the pending £9.99 Tesco payment is left out
    expect(result.transactions.some((x) => x.amount === -9.99)).toBe(false);
  });

  it("reads Revolut's 2026 layout: type codes, spaced thousands, FX lines, headings once, two periods", async () => {
    const bytes = readFileSync(new URL("revolut-2026.pdf", dir));
    const { result } = await readPdfStatement(pdfjs, bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength), parseWithMapping);
    const t = (p: string) => result.transactions.filter((x) => x.rawPayee === p);
    expect(t("Paypal *tcgplayer")[0]).toMatchObject({ amount: -2296.15, typeLabel: "CAR", kind: "spend" });
    // the $ amount under an FX line is not a transaction, and the " • reference" is stripped
    expect(result.transactions.some((x) => Math.abs(x.amount) === 63.29)).toBe(false);
    expect(t("Paypal Uk")[0]?.kind).toBe("internal");
    expect(result.transactions.every((x) => x.amount !== 0)).toBe(true);
    expect(result.dateRange?.to).toBe("2026-06-30");
  });

  it("says so when a PDF has no text (a scan)", () => {
    const pages: PdfPage[] = [{ items: [], width: 595, height: 842 }];
    const r = pdfToStatementCsv(pages);
    expect(r.noTable).toBe(true);
    expect(r.scanned).toBe(true);
    expect(r.warnings[0]).toMatch(/scan/);
  });

  it("reads a signed single amount column and dates with CR/DR markers", () => {
    const it = (str: string, x: number, y: number) => ({ str, x, y, w: str.length * 5, h: 9 });
    const pages: PdfPage[] = [{ width: 595, height: 842, items: [
      it("Date", 40, 800), it("Details", 110, 800), it("Amount", 400, 800), it("Balance", 500, 800),
      it("03/07/2026", 40, 780), it("TESCO STORES 3456", 110, 780), it("12.50 DR", 400, 780), it("100.00", 500, 780),
      it("04/07/2026", 40, 764), it("REFUND AMAZON", 110, 764), it("5.00 CR", 405, 764), it("105.00", 500, 764),
    ] }];
    const r = pdfToStatementCsv(pages);
    expect(r.rows).toBe(2);
    expect(r.csv.split("\n")[1]).toBe("2026-07-03,TESCO STORES 3456,TESCO STORES 3456,12.50,,100.00,GBP,");
    expect(r.csv.split("\n")[2]).toBe("2026-07-04,REFUND AMAZON,REFUND AMAZON,,5.00,105.00,GBP,");
  });
});
